<?php
require __DIR__.'/../config/config.php'; require_admin();
$action=$_GET['action']??'';$id=(int)($_GET['id']??0);$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$v=[trim($_POST['title']),$_POST['event_date'],trim($_POST['venue']),trim($_POST['description']),$_POST['status']];if($id){$s=db()->prepare("UPDATE events SET title=?,event_date=?,venue=?,description=?,status=? WHERE id=?");$s->execute([$v[0],$v[1],$v[2],$v[3],$v[4],$id]);}else{$s=db()->prepare("INSERT INTO events(title,event_date,venue,description,status) VALUES(?,?,?,?,?)");$s->execute($v);}$msg='Event saved.';$action='';}
if($action==='delete'&&$id){$s=db()->prepare("DELETE FROM events WHERE id=?");$s->execute([$id]);header('Location:events.php');exit;}
$edit=$id?db()->prepare("SELECT * FROM events WHERE id=?"):null;if($edit){$edit->execute([$id]);$row=$edit->fetch();}else{$row=['id'=>0,'title'=>'','event_date'=>date('Y-m-d'),'venue'=>'','description'=>'','status'=>'published'];}
$rows=db()->query("SELECT * FROM events ORDER BY event_date DESC,id DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events</title><link rel="stylesheet" href="admin.css"></head><body><div class="layout"><aside class="side"><h2>GBU ADMIN</h2><a href="index.php">Dashboard</a><a href="notices.php">Notices</a><a href="courses.php">Courses</a><a class="active" href="events.php">Events</a><a href="admins.php">Admins</a><a href="logout.php">Logout</a></aside><main class="main"><div class="top"><h1>Events</h1><a class="button gold" href="?action=new">+ New</a></div><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($action==='new'||$id):?><div class="panel"><h2><?= $id?'Edit':'Add' ?> Event</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><label>Title</label><input name="title" required value="<?=e($row['title'])?>"><div class="formgrid"><div><label>Date</label><input type="date" name="event_date" required value="<?=e($row['event_date'])?>"></div><div><label>Venue</label><input name="venue" value="<?=e($row['venue'])?>"></div></div><label>Description</label><textarea name="description" rows="4"><?=e($row['description'])?></textarea><label>Status</label><select name="status"><option value="published">Published</option><option value="draft">Draft</option></select><br><br><button class="button gold">Save</button> <a class="button" href="events.php">Cancel</a></form></div><?php endif;?><div class="panel"><table class="table"><tr><th>Title</th><th>Date</th><th>Venue</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['venue'])?></td><td><?=e($r['status'])?></td><td><a class="button" href="?id=<?=$r['id']?>">Edit</a> <a class="button danger" onclick="return confirm('Delete?')" href="?action=delete&id=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;?></table></div></main></div></body></html>